    x4 = _mm_add_epi32(x4, x7);
    x4 = _mm_sha256msg2_epu32(x4, x3);
    x0 = _mm_shuffle_epi32(x0, 0xe);
    x6 = _mm_sha256msg1_epu32(x6, x3);
    x1 = _mm_sha256rnds2_epu32(x1, x2, x0);
