    x6 = _mm_add_epi32(x6, x7);
    x6 = _mm_sha256msg2_epu32(x6, x5);
    x0 = _mm_shuffle_epi32(x0, 0xe);
    x4 = _mm_sha256msg1_epu32(x4, x5);
    x1 = _mm_sha256rnds2_epu32(x1, x2, x0);
    /* Rounds: 44-47 */
    x0 = x6;
    x0 = _mm_add_epi32(x0, _mm_loadu_si128((const __m128i*)WC_PR(rax, 176)));
    x2 = _mm_sha256rnds2_epu32(x2, x1, x0);
