    r9 = (word32)(WC_L32(rdi, 4));
    r10 = (word32)(WC_L32(rdi, 8));
    r11 = (word32)(WC_L32(rdi, 12));
    r12 = (word32)(WC_L32(rdi, 16));
    r13 = (word32)(WC_L32(rdi, 20));
    r14 = (word32)(WC_L32(rdi, 24));
    r15 = (word32)(WC_L32(rdi, 28));
