    x0 = _mm_shuffle_epi8(x0, x13);
    x1 = _mm_shuffle_epi8(x1, x13);
    x2 = _mm_loadu_si128((const __m128i*)WC_PR(rsi, 32));
    x3 = _mm_loadu_si128((const __m128i*)WC_PR(rsi, 48));
    x2 = _mm_shuffle_epi8(x2, x13);
    x3 = _mm_shuffle_epi8(x3, x13);
