    x4 = _mm_add_epi32(x0, _mm_loadu_si128((const __m128i*)WC_PR(rbp, 0)));
    x5 = _mm_add_epi32(x1, _mm_loadu_si128((const __m128i*)WC_PR(rbp, 16)));
    _mm_storeu_si128((__m128i*)WC_PW(rsp, 0), x4);
    _mm_storeu_si128((__m128i*)WC_PW(rsp, 16), x5);
    x6 = _mm_add_epi32(x2, _mm_loadu_si128((const __m128i*)WC_PR(rbp, 32)));
    x7 = _mm_add_epi32(x3, _mm_loadu_si128((const __m128i*)WC_PR(rbp, 48)));
    _mm_storeu_si128((__m128i*)WC_PW(rsp, 32), x6);
    _mm_storeu_si128((__m128i*)WC_PW(rsp, 48), x7);
    /* msg_sched: 0-3 */
    /* rnd_0: 0 - 0 */
    rdx = (word32)((((word32)rdx) >> 14) | (((word32)rdx) << 18));
    x5 = _mm_alignr_epi8(x1, x0, 4);
    x4 = _mm_alignr_epi8(x3, x2, 4);
    /* rnd_0: 1 - 2 */
    rax = (word32)((word32)r9);
    rcx = (word32)((word32)r13);
    r15 = (word32)((word32)r15 + WC_L32(rsp, 0));
    rcx = (word32)((word32)rcx ^ (word32)r14);
    rdx = (word32)((word32)rdx ^ (word32)r12);
    rcx = (word32)((word32)rcx & (word32)r12);
    x6 = _mm_srli_epi32(x5, 7);
